-- Sample "Formula 1 Analytics" multi-page dashboard.
--
-- Data: Ergast / Jolpica public F1 API (no auth) — 2025 season standings and
-- the 1950-2025 World & Constructor champions history, shipped as the
-- f1_* sample datasets (src/assets/sample-data). Widget snapshots were computed
-- from that data so the dashboard renders instantly and every widget's SQL
-- re-runs cleanly against the local engine.

-- Multi-page support for the sample template store.
ALTER TABLE public.bi_sample_dashboards
  ADD COLUMN IF NOT EXISTS pages jsonb NOT NULL DEFAULT '[]'::jsonb;

-- Copy pages too when seeding a user (mirrors bi_dashboards.pages).
CREATE OR REPLACE FUNCTION public.seed_bi_sample_dashboards(_uid uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.bi_dashboards (user_id, name, description, widgets, layout, pages, filters, theme)
  SELECT _uid, s.name, s.description, s.widgets, s.layout, s.pages, s.filters, s.theme
  FROM public.bi_sample_dashboards s
  WHERE NOT EXISTS (
    SELECT 1 FROM public.bi_dashboards d WHERE d.user_id = _uid AND d.name = s.name
  )
  ORDER BY s.sort;
END;
$$;

